import { FFmpeg } from '@ffmpeg/ffmpeg';
import { toBlobURL, fetchFile } from '@ffmpeg/util';

class VideoConverter {
  constructor() {
    this.ffmpeg = null;
    this.isLoaded = false;
    this.isLoading = false;
  }

  async loadFFmpeg(onProgress = null) {
    if (this.isLoaded || this.isLoading) return;
    
    this.isLoading = true;
    try {
      this.ffmpeg = new FFmpeg();
      
      // Set up progress logging if callback provided
      if (onProgress) {
        this.ffmpeg.on('log', ({ message }) => {
          // Parse FFmpeg progress from log messages
          const progressMatch = message.match(/time=(\d+:\d+:\d+\.\d+)/);
          if (progressMatch) {
            onProgress({ type: 'progress', message: `Converting: ${progressMatch[1]}` });
          }
          
          // Also look for other useful info
          if (message.includes('Duration:')) {
            const durationMatch = message.match(/Duration: (\d+:\d+:\d+\.\d+)/);
            if (durationMatch) {
              onProgress({ type: 'info', message: `Video duration: ${durationMatch[1]}` });
            }
          }
        });
      }

      // Load FFmpeg.wasm core and worker
      const baseURL = 'https://unpkg.com/@ffmpeg/core@0.12.6/dist/umd';
      await this.ffmpeg.load({
        coreURL: await toBlobURL(`${baseURL}/ffmpeg-core.js`, 'text/javascript'),
        wasmURL: await toBlobURL(`${baseURL}/ffmpeg-core.wasm`, 'application/wasm'),
      });
      
      this.isLoaded = true;
      this.isLoading = false;
      
      if (onProgress) {
        onProgress({ type: 'loaded', message: 'FFmpeg loaded successfully' });
      }
    } catch (error) {
      this.isLoading = false;
      throw new Error(`Failed to load FFmpeg: ${error.message}`);
    }
  }

  // Check if a video file needs conversion
  needsConversion(file) {
    const supportedFormats = ['mp4', 'webm', 'ogg'];
    const fileExt = file.name.toLowerCase().split('.').pop();
    
    // Common formats that typically need conversion
    const commonUnsupportedFormats = ['avi', 'mov', 'mkv', 'wmv', 'flv', 'asf', 'rm', 'rmvb', '3gp', 'f4v'];
    
    // If it's a known unsupported format, definitely needs conversion
    if (commonUnsupportedFormats.includes(fileExt)) {
      return true;
    }
    
    // If it's already a supported format, assume it's good
    if (supportedFormats.includes(fileExt)) {
      return false;
    }
    
    // For unknown formats, err on the side of caution and suggest conversion
    return true;
  }

  // Get video info using FFmpeg probe
  async getVideoInfo(file) {
    if (!this.isLoaded) {
      throw new Error('FFmpeg not loaded');
    }

    try {
      const inputName = 'input.' + file.name.split('.').pop();
      await this.ffmpeg.writeFile(inputName, await fetchFile(file));
      
      // Run ffprobe to get video information
      await this.ffmpeg.exec(['-i', inputName, '-f', 'null', '-']);
      
      // Clean up
      await this.ffmpeg.deleteFile(inputName);
      
      return { success: true };
    } catch (error) {
      return { success: false, error: error.message };
    }
  }

  // Convert video to MP4 H.264 format
  async convertToMP4(file, onProgress = null) {
    if (!this.isLoaded) {
      await this.loadFFmpeg(onProgress);
    }

    try {
      const inputExt = file.name.split('.').pop();
      const inputName = `input.${inputExt}`;
      const outputName = 'output.mp4';
      
      // Write input file to FFmpeg filesystem
      if (onProgress) onProgress({ type: 'progress', message: 'Preparing file for conversion...' });
      await this.ffmpeg.writeFile(inputName, await fetchFile(file));
      
      // Convert to MP4 with H.264 codec
      // Using fast preset for quicker conversion, with compatibility settings
      if (onProgress) onProgress({ type: 'progress', message: 'Starting conversion to MP4 H.264...' });
      
      await this.ffmpeg.exec([
        '-i', inputName,
        '-c:v', 'libx264',           // H.264 video codec
        '-preset', 'fast',           // Fast encoding preset
        '-crf', '23',                // Constant Rate Factor (good quality)
        '-c:a', 'aac',               // AAC audio codec
        '-movflags', 'faststart',    // Enable web streaming
        '-pix_fmt', 'yuv420p',       // Pixel format for compatibility
        '-y',                        // Overwrite output files
        outputName
      ]);
      
      // Read the converted file
      if (onProgress) onProgress({ type: 'progress', message: 'Finalizing conversion...' });
      const data = await this.ffmpeg.readFile(outputName);
      
      // Clean up temporary files
      await this.ffmpeg.deleteFile(inputName);
      await this.ffmpeg.deleteFile(outputName);
      
      // Create new File object from converted data
      const convertedBlob = new Blob([data.buffer], { type: 'video/mp4' });
      const originalNameWithoutExt = file.name.replace(/\.[^/.]+$/, '');
      const convertedFile = new File([convertedBlob], `${originalNameWithoutExt}_converted.mp4`, {
        type: 'video/mp4'
      });
      
      if (onProgress) onProgress({ type: 'complete', message: 'Conversion completed successfully!' });
      
      return {
        success: true,
        file: convertedFile,
        originalSize: file.size,
        convertedSize: convertedFile.size
      };
      
    } catch (error) {
      throw new Error(`Conversion failed: ${error.message}`);
    }
  }

  // Estimate conversion time based on file size (rough estimate)
  estimateConversionTime(fileSizeBytes) {
    // Very rough estimate: ~1 MB per second on average hardware
    const sizeInMB = fileSizeBytes / (1024 * 1024);
    const estimatedSeconds = Math.max(10, sizeInMB * 1.5); // Minimum 10 seconds
    return Math.round(estimatedSeconds);
  }

  // Format file size for display
  formatFileSize(bytes) {
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    if (bytes === 0) return '0 Bytes';
    const i = parseInt(Math.floor(Math.log(bytes) / Math.log(1024)));
    return Math.round(bytes / Math.pow(1024, i) * 100) / 100 + ' ' + sizes[i];
  }
}

// Export singleton instance
export const videoConverter = new VideoConverter(); 